787|    if (buffer_at_offset(input_buffer)[0] != '\"')
788|    {
789|        goto fail;
790|    }
791|
792|    {
793|        /* calculate approximate size of the output (overestimate) */
794|        size_t allocation_length = 0;
795|        size_t skipped_bytes = 0;
796|        while (((size_t)(input_end - input_buffer->content) < input_buffer->length) && (*input_end != '\"'))
